/**
 * Writes the version the way a project states it.
 *
 * A patch release is written out only when there is one, so the common case
 * reads as the minor version a support policy is stated in.
 *
 * @return string The version as text
 *
 * @example A minor version reads as its minor
 *     (new \App\Config\PhpVersion(80300))->toString() // => '8.3'
 * @example A patch release keeps its patch
 *     (new \App\Config\PhpVersion(80302))->toString() // => '8.3.2'
 */
public function toString(): string
